/* Brand marks, so each row carries the provider's own logo rather than a
   stand-in. Paths are the 24x24 marks from simple-icons (CC0); the logos
   themselves belong to their owners and are used here only to name the
   integration they connect to.

   Google Stitch has no published mark of its own, so its row carries
   Google's. */

/* How a server is connected.
 *
 *   "oauth"  The person signs in on the provider's own page and allows
 *            QuickStark — the MCP authorization flow (OAuth 2.1 with PKCE).
 *            Nobody pastes a key: a pasted key is a long-lived secret in a
 *            text box, copied through a clipboard, with no expiry and no way
 *            for the provider to show what it was granted to.
 *   "none"   Nothing to sign in to; enabling it is the whole connection.
 *
 * A custom server is "oauth" until its own response says otherwise: the
 * connect route asks it, and one that answers without asking for credentials
 * is saved as open. See src/lib/mcp/oauth.ts. */
export type McpAuth = "oauth" | "none";

export type McpServer = {
  id: string;
  name: string;
  description: string;
  auth: McpAuth;
  /* The server's MCP endpoint (Streamable HTTP). Where its sign-in is found,
     too: the server names its authorization server in its protected-resource
     metadata. Null for one with nothing remote to reach. */
  url: string | null;
  /* For a provider that does not register apps on the fly (Google), the
     environment prefix of the OAuth client registered for it once:
     `${prefix}_OAUTH_CLIENT_ID` and `${prefix}_OAUTH_CLIENT_SECRET`. */
  clientEnv?: string;
  /** Extra parameters the provider's authorize page needs — Google issues a
      refresh token only for offline access with a fresh consent. */
  authorizeParams?: Record<string, string>;
  /** 24x24 path data, or null for a server with no logo of its own. */
  path: string | null;
  tint: string;
  color: string;
};

/* The servers offered out of the box — the Connectors directory in Settings.
   A connection saved here is used read-only by the coding agent, and by a
   build whose request draws on it — see lib/mcp/runtime.ts. */

